mapper.update:
UPDATE retreat_group_members
SET retreat_group_id = #{groupId},
    leader = FALSE,
    display_order = (
        SELECT COALESCE(MAX(target.display_order) + 1, 0)
        FROM retreat_group_members target
        WHERE target.retreat_group_id = #{groupId}
          AND target.registration_id != #{participantId}
    ),
    updated_at = now()
WHERE registration_id = #{participantId}

UPDATE retreat_group_members
SET leader = TRUE,
    updated_at = now()
WHERE retreat_group_id = #{groupId}
  AND registration_id = #{participantId}

UPDATE retreat_group_members
SET display_order = #{displayOrder},
    updated_at = now()
WHERE retreat_group_id = #{groupId}
  AND registration_id = #{participantId}
